<div class="workspace-validation" x-show="messages('{{ $formKey }}').length" role="alert"><p>Perubahan belum disimpan. Periksa isian berikut:</p><ul><template x-for="(message, index) in messages('{{ $formKey }}')" :key="index"><li x-text="message"></li></template></ul></div>
<div class="workspace-save"><p class="workspace-save-feedback" x-bind:class="{ 'workspace-success': outcomes.{{ $formKey }}, 'workspace-field-error': feedback.{{ $formKey }} && !outcomes.{{ $formKey }} }" role="status" aria-live="polite" x-text="feedback.{{ $formKey }}"></p><button type="button" class="workspace-button" x-show="dirty('{{ $formKey }}')" x-on:click="reloadForm('{{ $formKey }}')" x-bind:disabled="mutationBusy()">Muat ulang bagian ini</button><button type="submit" class="workspace-button workspace-primary" x-bind:disabled="mutationBusy()" x-text="saving.{{ $formKey }} ? 'Menyimpan…' : '{{ $saveLabel }}'">{{ $saveLabel }}</button></div>
